    if (!get_single_block) {
      /* Copy to destination */
      memcpy((uint8_t *) dest + ntbytes, tmp2 + startb, (unsigned int) bsize2);
    }
    cbytes = (int)bsize2;
    ntbytes += cbytes;
  }

  return ntbytes;
}


